<div class="blog_listing_section">

  {% if blog_author %}

  {% if blog_author.avatar and blog_author.bio %}
  <div class="split-hero-wrapper hs-author-profile">
    <div class="split-hero-top"></div>
    <div class="split-hero-bottom blog-author">
      {% if blog_author.avatar %}
      <div class="about-author-page-img" style="background-image:url({{ blog_author.avatar }});"></div>
      {% else %}
      <div class="about-author-page-img" style="background-color:gray;"></div>
      {% endif %}
      <div class="module-max650">
        <h3 class="name">{{ blog_author.display_name }}</h3>
        <div class="content">
          {{ blog_author.bio }}
        </div>
      </div>
    </div>
  </div>
  {% endif %}

  {% endif %}

  <div class="main_listing">
    <div class="main_listing_inner">
      <!-- Recent Posts -->
      <div class="recent_posts_wrapper">
        <div class="headting_title clearfix">
          <div class="span6">
            <p class="recent_text">POST BY {{ blog_author.display_name }}</p>      
          </div>
          <div class="span6 cat_dropdown" style="display: none;">
            <div class="url_slug">{{ request.path|split('/', 3)|last|lower|replace('-', ' ') }}</div>
            <div class="tag_section">
              <div class="text">Posts by topic <i class="fa fa-angle-down" aria-hidden="true"></i></div>
              {% set topics_list = blog_topics('{{ group.id }}', 250) %}            
              <ul>
                {% for topic in topics_list %}
                <li><a href="{{ blog_tag_url(group.id, topic.slug) }}">{{ topic.name }}</a></li>
                {% endfor %}
              </ul>
            </div>            
          </div>
        </div>
        {# simple_list_page indicates the "blog/all" page, which is a list of links to every blog post #}
        <div class="post_listing clearfix {% if simple_list_page %}-simple{% endif %}">
          {% for content in contents %}
          <div class="post_item">
            <div class="inner">
              {% if not simple_list_page %}

              {% if content.post_list_summary_featured_image %}
              <div class="list_featured_img" style="background-image: url('{{ content.post_list_summary_featured_image }}');">
                <a href="{{content.absolute_url}}" title="" class="list_img_link"></a>                  
              </div>
              {% endif %}

              <div class="list_post_body clearfix">
                <div class="post_tags">
                  {% for topic in content.topic_list %}
                  <a href="{{ blog_tag_url(group.id, topic.slug) }}">{{ topic.name }}</a>
                  {% endfor %}                
                </div>
                <!--post summary-->
                <div class="post_header">
                  <h2><a href="{{content.absolute_url}}">{{ content.name }}</a></h2>
                </div>
                <div class="list_preview_text">
                  {{ content.post_list_content|truncatehtml(150, '...' , false) }}
                  <a class="list_preview_a" href="{{content.absolute_url}}"></a>
                </div>
                <!--
<div class="link_wrapper">
<a href="{{content.absolute_url}}">Read The Article</a>
</div>
-->
              </div>

              {% else %}
              <!-- Start: All listing page -->

              <div id="all_listing_page"></div>

              {% if content.post_list_summary_featured_image %}
              <div class="list_featured_img_wrapper">
                <a href="{{content.absolute_url}}" title="" class="list_img_link">
                  <img src="{{ content.post_list_summary_featured_image }}" class="list_featured_img">
                </a>
              </div>
              {% endif %}

              <div class="list_post_body clearfix">
                <!--post summary-->
                <div class="post_header">
                  <h2><a href="{{content.absolute_url}}">{{ content.name }}</a></h2>
                </div>
                <div class="list_preview_text">
                  {{ content.post_list_content|truncatehtml(120, '...' , false) }}
                  <a class="list_preview_a" href="{{content.absolute_url}}"></a>
                </div>
              </div>
              <!-- End: All listing page -->
              {% endif %}
            </div>
          </div>	

          {% endfor %}
        </div>
        <!--
<div class="bottom_post_tags">
<span>Topics:</span>
{% set topics_list_bottom = blog_topics('{{ group.id }}', 250) %}
{% for topic in topics_list_bottom %}
<a href="{{ blog_tag_url(group.id, topic.slug) }}">{{ topic.name }}</a>
{% endfor %}                
</div>
-->
        {#
        <div class="btn_section">
          <div class="load_more_btn btn_sec">More recent articles</div> <div class="all_articles_btn"><a class="btn_sec view-all" href="{{ group.absolute_url }}/all">View all articles</a></div>
        </div>
        #}
        {% if not simple_list_page %}
        <div class="btn_section">
          <div class="blog-pagination">
            {% if last_page_num %}
            <a class="previous-posts-link btn" href="{{ blog_page_link(last_page_num) }}">Previous</a>
            {% endif %}
            <a class="all-posts-link btn" href="{{ blog_all_posts_url(group.id) }}">All posts</a>
            {% if next_page_num %}
            <a class="next-posts-link btn" href="{{ blog_page_link(next_page_num) }}">Next</a>
            {% endif %}
          </div>
        </div>
        {% endif %}

